// dot4: 4-lane signed 8-bit dot product. Generated by the RTL agent.
// Architecture: latency 1, pipeline registers after: none.
module dot4 (
    input  logic               clk,
    input  logic               rst_n,
    input  logic               in_valid,
    input  logic        [31:0] a,
    input  logic        [31:0] b,
    output logic               out_valid,
    output logic signed [17:0] y
);
    localparam int LAT = 1;

    // input registers
    logic signed [7:0] ar [4], br [4];
    always_ff @(posedge clk)
        if (in_valid)
            for (int k = 0; k < 4; k++) begin
                ar[k] <= a[8*k +: 8];
                br[k] <= b[8*k +: 8];
            end

    logic signed [15:0] p [4];
    always_comb for (int k = 0; k < 4; k++) p[k] = 16'(ar[k]) * 16'(br[k]);

    // balanced adder tree
    logic signed [16:0] s01, s23;
    assign s01 = 17'(p[0]) + 17'(p[1]);
    assign s23 = 17'(p[2]) + 17'(p[3]);

    // output register
    always_ff @(posedge clk)
        y <= 18'(s01) + 18'(s23);

    // valid pipeline: the only state that needs a reset
    logic [LAT:0] v;
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) v <= '0;
        else        v <= {v[LAT-1:0], in_valid};
    assign out_valid = v[LAT];
endmodule
